CREATE TABLE IF NOT EXISTS governance_bodies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, body_type text NOT NULL, jurisdiction_id uuid REFERENCES jurisdictions(id), parent_body_id uuid REFERENCES governance_bodies(id), mandate text NOT NULL, independence_requirement text, quorum_rule text, voting_rule text, reserved_matter_scope text, status text NOT NULL DEFAULT 'Proposed', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, person_reference text NOT NULL, role text NOT NULL, appointment_basis text, appointment_date date, term_end_date date, voting_right boolean NOT NULL DEFAULT true, independence_status text, conflict_status text NOT NULL DEFAULT 'Not Declared', status text NOT NULL DEFAULT 'Proposed', evidence_reference text);
CREATE TABLE IF NOT EXISTS governance_mandates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, mandate_area text NOT NULL, authority_level text NOT NULL, decision_right text NOT NULL, escalation_route text, reserved_matter boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS governance_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, meeting_date date NOT NULL, meeting_type text NOT NULL, quorum_met boolean, attendees text, conflicts_declared text, agenda_reference text, minutes_reference text, status text NOT NULL DEFAULT 'Planned');
CREATE TABLE IF NOT EXISTS governance_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, meeting_id uuid REFERENCES governance_meetings(id), resolution_code text NOT NULL, title text NOT NULL, resolution_text text NOT NULL, decision_status text NOT NULL DEFAULT 'Proposed', votes_for integer DEFAULT 0, votes_against integer DEFAULT 0, abstentions integer DEFAULT 0, conflict_recusals integer DEFAULT 0, effective_date date, evidence_reference text, status text NOT NULL DEFAULT 'Draft');
CREATE TABLE IF NOT EXISTS governance_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, person_reference text NOT NULL, matter_reference text NOT NULL, conflict_type text NOT NULL, declared_date date NOT NULL DEFAULT current_date, mitigation text, recusal_required boolean NOT NULL DEFAULT true, recusal_recorded boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Open', evidence_reference text);
CREATE TABLE IF NOT EXISTS governance_reserved_matters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, matter_code text NOT NULL, title text NOT NULL, approval_route text NOT NULL, unanimity_required boolean NOT NULL DEFAULT false, supermajority_percentage numeric, community_rights_review boolean NOT NULL DEFAULT false, independent_review boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS governance_delegations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delegating_body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, receiving_body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, authority_area text NOT NULL, monetary_limit numeric, currency text, conditions text, start_date date, end_date date, revocable boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS governance_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), body_id uuid REFERENCES governance_bodies(id) ON DELETE CASCADE, evidence_type text NOT NULL, reference text NOT NULL, verified_by text, verified_date date, status text NOT NULL DEFAULT 'Unverified', notes text);
INSERT INTO governance_bodies(entity_name,body_code,body_name,mandate,quorum_rule,voting_rule,chair_rule,status) SELECT 'OSANVAULT AFRICA LTD','GROUP-BOARD','Group Board of Directors','Ultimate oversight of the Group, strategy, fiduciary stewardship, risk, capital allocation and reserved matters.','Majority of serving voting members unless applicable law requires more.','Simple majority unless a reserved matter requires a higher threshold.','Chair subject to applicable law and conflict rules.','Active' WHERE NOT EXISTS (SELECT 1 FROM governance_bodies WHERE body_code='GROUP-BOARD');
INSERT INTO governance_bodies(entity_name,body_code,body_name,mandate,quorum_rule,voting_rule,chair_rule,status) SELECT 'OSANVAULT AFRICA LTD','ARC-COMMITTEE','Audit, Risk & Compliance Committee','Independent oversight of financial integrity, enterprise risk, compliance, internal controls, audit and remediation.','Two voting members including the chair or designated independent member.','Simple majority; conflicted members recuse.','Independent chair where practicable.','Active' WHERE NOT EXISTS (SELECT 1 FROM governance_bodies WHERE body_code='ARC-COMMITTEE');
INSERT INTO governance_bodies(entity_name,body_code,body_name,mandate,quorum_rule,voting_rule,chair_rule,status) SELECT 'OSANVAULT AFRICA LTD','ETHICS-STEWARDSHIP','Ethics & Stewardship Committee','Protect institutional integrity, indigenous and community rights, environmental safeguards, protected assets, ethics and grievance escalation.','Two voting members with at least one stewardship-qualified member.','Simple majority; conflicts require recusal.','Stewardship-qualified chair for protected-rights matters.','Active' WHERE NOT EXISTS (SELECT 1 FROM governance_bodies WHERE body_code='ETHICS-STEWARDSHIP');
INSERT INTO governance_bodies(entity_name,body_code,body_name,mandate,quorum_rule,voting_rule,chair_rule,status) SELECT 'OSANVAULT AFRICA LTD','INVESTMENT-CAPITAL','Investment & Capital Committee','Evaluate investments, capital deployment, portfolio concentration, liquidity, returns and downside protection.','Two voting members.','Simple majority subject to Board reserved matters.','Conflict-free chair required for material decisions.','Active' WHERE NOT EXISTS (SELECT 1 FROM governance_bodies WHERE body_code='INVESTMENT-CAPITAL');
INSERT INTO governance_reserved_matters(matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes,status) SELECT 'RM-001','Constitution','Change to Group Constitution','Group Board + applicable shareholders','75% supermajority','Independent review','Constitutional changes must comply with applicable company law and the adopted Group constitution.','Proposed' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-001');
INSERT INTO governance_reserved_matters(matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes,status) SELECT 'RM-002','Protected Rights','Protected or Community-Linked Asset Decision','Board + Ethics & Stewardship Committee','Rights and evidence gate','Independent review where material','Land, mineral, cultural, carbon and community-linked decisions require jurisdiction-specific rights review.','Proposed' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-002');
INSERT INTO governance_reserved_matters(matter_code,category,matter_title,approval_authority,decision_standard,secondary_approval,notes,status) SELECT 'RM-003','Corporate Structure','Creation of Material Subsidiary or SPV','Group Board + Legal + Finance','Board approval','Legal and jurisdiction review','New entities require a defined purpose, jurisdiction, ownership, authority, compliance and evidence trail.','Proposed' WHERE NOT EXISTS (SELECT 1 FROM governance_reserved_matters WHERE matter_code='RM-003');